let frase = "javascript";
const maiusculas = frase.toUpperCase();

console.log(frase); // "javascript" - original inalterada
console.log(maiusculas); // "JAVASCRIPT" - string nova e independente

frase = frase + "!"; // reatribuição: a variável passa a apontar para uma string nova
console.log(frase); // "javascript!"

const a = 10;
let b = a; // b recebe uma cópia independente do valor 10
b = b + 5;
console.log(a, b); // 10 15 - a não foi afetado

// Primitivos: cópia por valor
let x = 5;
let y = x;
y = 10;
console.log(x, y); // 5 10 - independentes

// Objetos: cópia por referência
const pessoa1 = { nome: "Rui" };
const pessoa2 = pessoa1; // mesma referência
pessoa2.nome = "Sofia";
console.log(pessoa1.nome); // "Sofia" - o mesmo objeto foi alterado

// const impede reatribuir a variável, não alterar o objeto
const config = { tema: "escuro" };
config.tema = "claro"; // permitido
// config = {}; // erro: Assignment to constant variable.

console.log({ a: 1 } === { a: 1 }); // false - referências diferentes

let variavel;
console.log(variavel); // undefined - declarada, nunca inicializada

function saudacao(nome) {
  console.log(nome); // undefined, se a função for chamada sem argumento
}
saudacao();

const pessoa = { nome: "Marta" };
console.log(pessoa.idade); // undefined - propriedade que não existe

let resultado = null; // ausência de valor definida deliberadamente

console.log(null === undefined); // false - tipos diferentes
console.log(null == undefined); // true - comparação solta trata-os como equivalentes
console.log(typeof null); // "object"
console.log(typeof undefined); // "undefined"

