const nome = "Adriano";
const idade = 30;
const ativo = true;
let semValor;
const nulo = null;
const numeroGrande = 100n;

console.log(typeof nome); // "string"
console.log(typeof idade); // "number"
console.log(typeof ativo); // "boolean"
console.log(typeof semValor); // "undefined"
console.log(typeof nulo); // "object"
console.log(typeof numeroGrande); // "bigint"

function dobrarPrimeiro(numeros, valor) {
  valor = valor * 2; // altera apenas a cópia local do primitivo
  numeros[0] = numeros[0] * 2; // altera o array original, porque é passado por referência
  return valor;
}

let numeroOriginal = 5;
const listaOriginal = [10, 20, 30];

const resultado = dobrarPrimeiro(listaOriginal, numeroOriginal);

console.log(numeroOriginal); // 5 - inalterado, era um primitivo copiado por valor
console.log(resultado); // 10 - o dobro, devolvido pela função
console.log(listaOriginal); // [20, 20, 30] - o primeiro elemento foi alterado, mesma referência

function valorOuPadrao(valor, padrao) {
  if (valor == null) {
    // == null apanha tanto null como undefined, e só esses dois casos
    return padrao;
  }
  return valor;
}

console.log(valorOuPadrao(0, "padrão")); // 0 - 0 não é null nem undefined
console.log(valorOuPadrao("", "padrão")); // "" - string vazia não é null nem undefined
console.log(valorOuPadrao(false, "padrão")); // false - idem
console.log(valorOuPadrao(null, "padrão")); // "padrão" - null é substituído
console.log(valorOuPadrao(undefined, "padrão")); // "padrão" - undefined é substituído
